#!/usr/bin/env python3
"""Durable key-value HTTP service.

Endpoints:
  GET  /health         -> 200 "ready"
  PUT  /records/<id>   -> 204 (stores request body)
  GET  /records/<id>   -> 200 (returns exact stored body)
"""
import os
import re
import sys
import tempfile
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

PORT = 8080
DATA_DIR = "/var/lib/builder-app/records"
ID_RE = re.compile(r"^[A-Za-z0-9._-]+$")


class Handler(BaseHTTPRequestHandler):
    server_version = "builder-app/1.0"
    protocol_version = "HTTP/1.1"

    def _send(self, code, body=b"", ctype="application/octet-stream", extra=None):
        self.send_response(code)
        self.send_header("Content-Type", ctype)
        self.send_header("Content-Length", str(len(body)))
        if extra:
            for k, v in extra.items():
                self.send_header(k, v)
        self.end_headers()
        if body and self.command != "HEAD":
            try:
                self.wfile.write(body)
            except BrokenPipeError:
                pass

    def _record_path(self, id_):
        if not ID_RE.match(id_):
            return None
        return os.path.join(DATA_DIR, id_)

    def do_GET(self):
        if self.path == "/health":
            self._send(200, b"ready", "text/plain; charset=utf-8")
            return
        m = re.match(r"^/records/([^/]+)$", self.path)
        if not m:
            self._send(404, b"not found")
            return
        path = self._record_path(m.group(1))
        if path is None or not os.path.exists(path):
            self._send(404, b"not found")
            return
        with open(path, "rb") as f:
            body = f.read()
        self._send(200, body, "application/octet-stream")

    def do_PUT(self):
        m = re.match(r"^/records/([^/]+)$", self.path)
        if not m:
            self._send(404, b"not found")
            return
        path = self._record_path(m.group(1))
        if path is None:
            self._send(400, b"bad id")
            return
        length = int(self.headers.get("Content-Length") or 0)
        body = self.rfile.read(length) if length > 0 else b""
        self._store(path, body)
        self._send(204, b"")

    def do_HEAD(self):
        if self.path == "/health":
            self._send(200, b"ready", "text/plain; charset=utf-8")
            return
        self._send(404, b"")

    def _store(self, path, body):
        os.makedirs(os.path.dirname(path), exist_ok=True)
        dir_ = os.path.dirname(path)
        fd, tmp = tempfile.mkstemp(dir=dir_, prefix=".tmp-", suffix=".rec")
        try:
            os.write(fd, body)
            os.fsync(fd)
            os.close(fd)
            os.replace(tmp, path)
            # fsync the directory so the rename is durable
            try:
                dfd = os.open(dir_, os.O_RDONLY)
                try:
                    os.fsync(dfd)
                finally:
                    os.close(dfd)
            except OSError:
                pass
        except Exception:
            try:
                os.close(fd)
            except OSError:
                pass
            try:
                os.unlink(tmp)
            except OSError:
                pass
            raise

    def log_message(self, fmt, *args):
        sys.stderr.write("%s - - [%s] %s\n" % (self.client_address[0], self.log_date_time_string(), fmt % args))


def main():
    os.makedirs(DATA_DIR, exist_ok=True)
    httpd = ThreadingHTTPServer(("0.0.0.0", PORT), Handler)
    httpd.daemon_threads = True
    sys.stderr.write("builder-app listening on :%d, data=%s\n" % (PORT, DATA_DIR))
    try:
        httpd.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        httpd.server_close()


if __name__ == "__main__":
    main()

